// === TurboModule：定义原生模块接口 ===
// NativeCalculator.ts
import type { TurboModule } from 'react-native';
import { TurboModuleRegistry } from 'react-native';

export interface Spec extends TurboModule {
  // Codegen 会根据这个类型定义自动生成 C++/Java/ObjC 接口
  add(a: number, b: number): Promise<number>;
  getVersion(): string; // 同步调用，JSI 直接返回
}

// getEnforcing 表示模块必须存在，不存在则报错
// get 返回 null，适合可选模块
export default TurboModuleRegistry.getEnforcing<Spec>('NativeCalculator');

// === Fabric 组件：定义原生 UI 组件 ===
// MyNativeViewNativeComponent.ts
type NativeProps = {
  color: string;
  size: number;
};

// codegenNativeComponent 替代旧的 requireNativeComponent
// Codegen 自动生成类型安全的视图管理器代码
import codegenNativeComponent from 'react-native/Libraries/Utilities/codegenNativeComponent';
export default codegenNativeComponent<NativeProps>('MyNativeView');

// === 使用 TurboModule 和 Fabric 组件 ===
import React, { useEffect, useState } from 'react';
import { View, Text, FlatList, StyleSheet, TouchableOpacity } from 'react-native';
import NativeCalculator from './NativeCalculator'; // TurboModule
import MyNativeView from './MyNativeView'; // Fabric 组件

function App() {
  const [version, setVersion] = useState('');
  useEffect(() => {
    // 同步调用经过 JSI，无 Bridge 序列化
    setVersion(NativeCalculator.getVersion());
  }, []);

  return (
    <View style={styles.container}>
      <Text>Native Version: {version}</Text>
      {/* Fabric 组件直接在新渲染器下工作 */}
      <MyNativeView color="#4A90D9" size={200} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 }
});

// === CodePush 热更新配置 ===
import codePush from 'react-native-code-push';

// 包裹根组件，应用启动时检查更新
const App = codePush({
  checkFrequency: codePush.CheckFrequency.ON_APP_RESUME,
  installMode: codePush.InstallMode.ON_NEXT_RESTART
})(RootComponent);

